/*global define*/

define(
    'example/worker/src/FibonacciIndicator',[],
    function () {
        "use strict";

        /**
         * Displays Fibonacci numbers in the status area.
         * @constructor
         */
        function FibonacciIndicator(workerService, $rootScope) {
            var latest,
                counter = 0,
                worker = workerService.run('example.fibonacci');

            function requestNext() {
                worker.postMessage([counter]);
                counter += 1;
            }

            function handleResponse(event) {
                latest = event.data;
                $rootScope.$apply();
                requestNext();
            }

            worker.onmessage = handleResponse;
            requestNext();

            return {
                getCssClass: function () {
                    return "icon-object-unknown";
                },
                getText: function () {
                    return latest;
                },
                getDescription: function () {
                    return "";
                }
            };
        }

        return FibonacciIndicator;
    }
);

